import 'package:flutter/material.dart';
void main()=>runApp(const StudioApp());
class StudioApp extends StatelessWidget{const StudioApp({super.key});@override Widget build(BuildContext context){const gold=Color(0xFFE8C170);return MaterialApp(debugShowCheckedModeBanner:false,title:'Subtitle Studio AI',theme:ThemeData(brightness:Brightness.dark,scaffoldBackgroundColor:const Color(0xFF07111F),colorScheme:ColorScheme.fromSeed(seedColor:gold,brightness:Brightness.dark),useMaterial3:true),home:const HomePage());}}
